def words(text):
    return text.split(' ')


def word_count(text):
    return len(words(text))


def longest(text):
    return max(words(text), key=len

from taskqueue.persist import Journal


class JobQueue:
    def __init__(self):
        self.jobs = []

    def push(self, name, priority):
        self.jobs.append((priority, name))

    def pop(self):
        self.jobs.sort()
        return self.jobs.pop(0)[1]

    def __len__(self):
        return len(self.jobs)
